create function public.current_user_role() returns public.account_role language sql stable security definer set search_path='' as $$select role from public.profiles where id=auth.uid() and suspended_at is null$$;
create function public.is_staff() returns boolean language sql stable security definer set search_path='' as $$select coalesce(public.current_user_role() in ('STAFF','ADMIN'),false)$$;
create function public.protect_profile_privileges() returns trigger language plpgsql security definer set search_path='' as $$begin if auth.uid()=old.id and public.current_user_role()<>'ADMIN' then new.role=old.role; new.suspended_at=old.suspended_at; end if; return new; end$$;
create trigger protect_profile_privileges before update on public.profiles for each row execute function public.protect_profile_privileges();
alter table public.courses enable row level security; alter table public.profiles enable row level security; alter table public.posts enable row level security; alter table public.post_images enable row level security; alter table public.post_likes enable row level security; alter table public.comments enable row level security; alter table public.post_reports enable row level security; alter table public.support_alerts enable row level security; alter table public.support_alert_notes enable row level security; alter table public.support_alert_events enable row level security; alter table public.notifications enable row level security; alter table public.audit_logs enable row level security;
create policy courses_read on public.courses for select to authenticated using(active or public.is_staff());
create policy profiles_read on public.profiles for select to authenticated using(suspended_at is null or id=auth.uid() or public.current_user_role()='ADMIN');
create policy profiles_self_update on public.profiles for update to authenticated using(id=auth.uid() or public.current_user_role()='ADMIN') with check(id=auth.uid() or public.current_user_role()='ADMIN');
create policy posts_read on public.posts for select to authenticated using((hidden_at is null and deleted_at is null) or author_id=auth.uid() or public.is_staff());
create policy posts_insert on public.posts for insert to authenticated with check(author_id=auth.uid() and public.current_user_role() is not null and (not official or public.current_user_role() in ('TEACHER','STAFF','ADMIN')) and (not pinned or public.current_user_role() in ('TEACHER','STAFF','ADMIN')));
create policy posts_update on public.posts for update to authenticated using(author_id=auth.uid() or public.is_staff()) with check(author_id=auth.uid() or public.is_staff());
create policy images_read on public.post_images for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id)); create policy images_write on public.post_images for insert to authenticated with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid())); create policy images_delete on public.post_images for delete to authenticated using(exists(select 1 from public.posts p where p.id=post_id and (p.author_id=auth.uid() or public.is_staff())));
create policy likes_read on public.post_likes for select to authenticated using(true); create policy likes_add on public.post_likes for insert to authenticated with check(user_id=auth.uid() and public.current_user_role() is not null); create policy likes_remove on public.post_likes for delete to authenticated using(user_id=auth.uid());
create policy comments_read on public.comments for select to authenticated using(hidden_at is null or author_id=auth.uid() or public.is_staff()); create policy comments_add on public.comments for insert to authenticated with check(author_id=auth.uid() and public.current_user_role() is not null); create policy comments_update on public.comments for update to authenticated using(author_id=auth.uid() or public.is_staff()) with check(author_id=auth.uid() or public.is_staff()); create policy comments_delete on public.comments for delete to authenticated using(author_id=auth.uid() or public.is_staff());
create policy reports_add on public.post_reports for insert to authenticated with check(reporter_id=auth.uid()); create policy reports_staff on public.post_reports for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy alerts_read on public.support_alerts for select to authenticated using(author_id=auth.uid() or public.is_staff()); create policy alerts_add on public.support_alerts for insert to authenticated with check(author_id=auth.uid() and public.current_user_role() is not null); create policy alerts_staff_update on public.support_alerts for update to authenticated using(public.is_staff()) with check(public.is_staff());
create policy notes_staff on public.support_alert_notes for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy events_read on public.support_alert_events for select to authenticated using(public.is_staff() or (coalesce((metadata->>'internal')::boolean,false)=false and exists(select 1 from public.support_alerts a where a.id=alert_id and a.author_id=auth.uid()))); create policy events_staff_add on public.support_alert_events for insert to authenticated with check(public.is_staff());
create policy notifications_self_read on public.notifications for select to authenticated using(recipient_id=auth.uid()); create policy notifications_self_update on public.notifications for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
create policy audit_admin on public.audit_logs for select to authenticated using(public.current_user_role()='ADMIN'); create policy audit_staff_add on public.audit_logs for insert to authenticated with check(actor_id=auth.uid() and public.is_staff());
